"use server";

/**
 * Posts a comment and fans out mention notifications; rate limited.
 *
 * Owner D. The notification fan-out itself is not triggered here — the service
 * emits `comment.created` and `NotificationService` subscribes to it. This
 * action only validates, authorizes, charges the rate limit and revalidates.
 *
 * Must call (do not reimplement): createCommentSchema, can, consumeRateLimit,
 * getActor, toActionResult
 */

import { ForbiddenActionError, RateLimitedError } from "@/actions/_lib/action-errors";
import { PENDING_COMMENT_ID } from "@/actions/_lib/permission-resources";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, issueTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { createCommentSchema, type CreateCommentInput } from "@/schemas/comment";
import { createComment } from "@/server/services/comment-service";
import type { ActionResult } from "@/types/api";
import type { Comment } from "@/types/comment";

const COMMENT_BUCKET = "comment:create";

const run = withAction<typeof createCommentSchema, Comment>(
  createCommentSchema,
  async (raw, actor) => {
    const input = raw as CreateCommentInput;

    const allowed = can(actor, "comment:create", {
      kind: "comment",
      orgId: input.orgId,
      commentId: PENDING_COMMENT_ID,
      authorId: actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("comment:create");
    }

    const verdict = await consumeRateLimit(input.orgId, COMMENT_BUCKET);
    if (!verdict.allowed) {
      throw new RateLimitedError(COMMENT_BUCKET, verdict.resetAt);
    }

    const comment = await createComment(actor, input);
    revalidateTagged([issueTag(input.issueId)], CACHE_PROFILES.seconds);
    return comment;
  },
  { revalidate: ["comments"], cacheProfile: "seconds" },
);

export async function createCommentAction(raw: unknown): Promise<ActionResult<Comment>> {
  return run(raw);
}
"use server";

/**
 * Soft-deletes a comment.
 *
 * Owner D. Deletion is a soft delete: `CommentService` stamps `archived_at`
 * through `archivePatch()` and the thread query filters it out, so replies
 * hanging off the comment keep their parent id.
 *
 * Must call (do not reimplement): deleteCommentSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, issueTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { deleteCommentSchema, type DeleteCommentInput } from "@/schemas/comment";
import { deleteComment } from "@/server/services/comment-service";
import type { ActionResult } from "@/types/api";
import type { Comment } from "@/types/comment";

const run = withAction<typeof deleteCommentSchema, Comment>(
  deleteCommentSchema,
  async (raw, actor) => {
    const input = raw as DeleteCommentInput;

    const allowed = can(actor, "comment:delete", {
      kind: "comment",
      orgId: input.orgId,
      commentId: input.commentId,
      authorId: actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("comment:delete");
    }

    const comment = await deleteComment(actor, input);
    revalidateTagged([issueTag(comment.issueId)], CACHE_PROFILES.seconds);
    return comment;
  },
  { revalidate: ["comments"], cacheProfile: "seconds" },
);

export async function deleteCommentAction(raw: unknown): Promise<ActionResult<Comment>> {
  return run(raw);
}
"use server";

/**
 * Edits a comment the actor authored.
 *
 * Owner D. The `can()` call here is an optimistic pre-check made with the
 * caller as the presumed author, so a viewer is rejected before the round trip;
 * `CommentService.updateComment` repeats the check with the persisted
 * `authorId`, which is what actually enforces "only your own comments".
 *
 * Must call (do not reimplement): updateCommentSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { updateCommentSchema, type UpdateCommentInput } from "@/schemas/comment";
import { updateComment } from "@/server/services/comment-service";
import type { ActionResult } from "@/types/api";
import type { Comment } from "@/types/comment";

const run = withAction<typeof updateCommentSchema, Comment>(
  updateCommentSchema,
  async (raw, actor) => {
    const input = raw as UpdateCommentInput;

    const allowed = can(actor, "comment:update", {
      kind: "comment",
      orgId: input.orgId,
      commentId: input.commentId,
      authorId: actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("comment:update");
    }

    const comment = await updateComment(actor, input);
    revalidateTagged(["comments"], CACHE_PROFILES.seconds);
    return comment;
  },
  { revalidate: ["comments"], cacheProfile: "seconds" },
);

export async function updateCommentAction(raw: unknown): Promise<ActionResult<Comment>> {
  return run(raw);
}
/**
 * Threaded comment list, hiding delete for non-authors.
 *
 * Must call (do not reimplement): can
 */
import { EmptyState } from "@/components/ui/empty-state";
import { can } from "@/lib/permissions";
import { isLive } from "@/lib/soft-delete";
import type { CommentId } from "@/types/common";
import type { CommentThreadNode } from "@/types/comment";
import type { Actor } from "@/types/member";
import type { ReactElement } from "react";
import { organizationResource } from "../permission/resources";
import { CommentItem } from "./comment-item";

export type CommentThreadProps = {
  nodes: readonly CommentThreadNode[];
  actor: Actor;
  onDelete: (commentId: CommentId) => void;
  onEdit?: (commentId: CommentId) => void;
};

/** Oldest first: a discussion reads top to bottom, unlike a feed. */
export function orderThread(
  nodes: readonly CommentThreadNode[],
): readonly CommentThreadNode[] {
  return [...nodes].sort((a, b) =>
    a.comment.createdAt.localeCompare(b.comment.createdAt),
  );
}

export function CommentThread(props: CommentThreadProps): ReactElement | null {
  const { nodes, actor, onDelete, onEdit } = props;

  if (!can(actor, "comment:read", organizationResource(actor.orgId))) {
    return null;
  }

  const visible = orderThread(nodes).filter((node) => isLive(node.comment));

  if (visible.length === 0) {
    return <EmptyState title="No comments yet" description="Start the thread." />;
  }

  return (
    <ol className="comment-thread divide-y">
      {visible.map((node) => (
        <li key={node.comment.id}>
          <ol>
            <CommentItem
              comment={node.comment}
              actor={actor}
              depth={0}
              onDelete={onDelete}
              {...(onEdit !== undefined ? { onEdit } : {})}
            />
            {node.replies
              .filter(isLive)
              .sort((a, b) => a.createdAt.localeCompare(b.createdAt))
              .map((reply) => (
                <CommentItem
                  key={reply.id}
                  comment={reply}
                  actor={actor}
                  depth={1}
                  onDelete={onDelete}
                  {...(onEdit !== undefined ? { onEdit } : {})}
                />
              ))}
          </ol>
        </li>
      ))}
    </ol>
  );
}
/**
 * One comment with author, timestamp and inline actions.
 *
 * Must call (do not reimplement): can
 */
import { Avatar } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/cn";
import { formatRelative } from "@/lib/date";
import { highlightMentions } from "@/lib/mentions";
import { can } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import type { CommentId } from "@/types/common";
import type { CommentWithAuthor } from "@/types/comment";
import type { Actor } from "@/types/member";
import type { ReactElement } from "react";
import { commentResource } from "../permission/resources";

export type CommentItemProps = {
  comment: CommentWithAuthor;
  actor: Actor;
  depth: number;
  onEdit?: (commentId: CommentId) => void;
  onDelete?: (commentId: CommentId) => void;
};

/** Replies are indented once; deeper nesting is flattened by the thread. */
const INDENT_REM = 2;

export function CommentItem(props: CommentItemProps): ReactElement | null {
  const { comment, actor, depth, onEdit, onDelete } = props;
  const resource = commentResource(comment);

  // Authors may edit and delete their own comments below the matrix rank —
  // that escalation lives in `can()`, not here.
  const mayEdit = can(actor, "comment:update", resource);
  const mayDelete = can(actor, "comment:delete", resource);

  if (isArchived(comment)) {
    return (
      <li className="text-sm italic text-neutral-500">
        This comment was deleted.
      </li>
    );
  }

  return (
    <li
      className={cn("comment-item flex gap-2 py-2")}
      style={{ marginLeft: `${Math.min(depth, 1) * INDENT_REM}rem` }}
    >
      <Avatar
        name={comment.author.name}
        src={comment.author.avatarUrl}
        size="sm"
      />

      <div className="min-w-0 flex-1">
        <p className="text-sm">
          <strong>{comment.author.name}</strong>
          <span className="ml-2 text-neutral-500">
            {formatRelative(comment.createdAt)}
          </span>
          {comment.editedAt !== null ? (
            <span className="ml-2 text-xs text-neutral-400">(edited)</span>
          ) : null}
        </p>

        <div
          className="mt-1 text-sm"
          dangerouslySetInnerHTML={{ __html: highlightMentions(comment.body) }}
        />

        {mayEdit || mayDelete ? (
          <div className="mt-1 flex gap-1">
            {mayEdit && onEdit !== undefined ? (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => onEdit(comment.id)}
              >
                Edit
              </Button>
            ) : null}
            {mayDelete && onDelete !== undefined ? (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => onDelete(comment.id)}
              >
                Delete
              </Button>
            ) : null}
          </div>
        ) : null}
      </div>
    </li>
  );
}

/**
 * Comment rows, soft deleted so a deleted comment keeps its place in the thread.
 *
 * Must call (do not reimplement): archivePatch, shouldFilterArchived
 */
import { and, asc, count, desc, eq, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { archivePatch, shouldFilterArchived } from "@/lib/soft-delete";
import { comments, getDb, users } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toComment, toUser } from "./_mappers";
import type {
  CreateCommentInput,
  ListCommentsInput,
  UpdateCommentInput,
} from "@/schemas/comment";
import type {
  Comment,
  CommentThreadNode,
  CommentWithAuthor,
} from "@/types/comment";
import type { CommentId, IssueId, OrgId, Page, UserId } from "@/types/common";

export async function findCommentById(
  orgId: OrgId,
  commentId: CommentId,
): Promise<Comment | null> {
  const row = getDb()
    .select()
    .from(comments)
    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))
    .get();
  return row ? toComment(row) : null;
}

export async function listComments(
  input: ListCommentsInput,
): Promise<Page<CommentWithAuthor>> {
  const db = getDb();
  const sort = { sortColumn: comments.createdAt, idColumn: comments.id };

  const filters = compact(
    orgPredicate(comments.orgId, input.orgId),
    eq(comments.issueId, input.issueId),
    shouldFilterArchived(input) ? isNull(comments.archivedAt) : undefined,
  );

  const total = db
    .select({ value: count() })
    .from(comments)
    .where(and(...filters))
    .get();

  const rows = db
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(comments.createdAt), desc(comments.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => ({ ...toComment(row.comment), author: toUser(row.author) }),
    (row) => ({ id: row.comment.id, sortValue: row.comment.createdAt }),
  );
}

/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first, each followed by its replies. A deleted top-level comment takes its
 * thread with it — nothing to anchor the replies to once the opener is gone.
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt))
    .all();

  const decorated: CommentWithAuthor[] = rows.map((row) => ({
    ...toComment(row.comment),
    author: toUser(row.author),
  }));

  const repliesBy = new Map<string, CommentWithAuthor[]>();
  for (const comment of decorated) {
    if (comment.parentId === null) continue;
    const bucket = repliesBy.get(comment.parentId) ?? [];
    bucket.push(comment);
    repliesBy.set(comment.parentId, bucket);
  }

  return decorated
    .filter((comment) => comment.parentId === null && comment.archivedAt === null)
    .map((comment) => ({
      comment,
      replies: repliesBy.get(comment.id) ?? [],
    }));
}

export async function countComments(
  orgId: OrgId,
  issueId: IssueId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(comments)
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
        isNull(comments.archivedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertComment(
  input: CreateCommentInput,
  authorId: UserId,
): Promise<Comment> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(comments)
    .values({
      id: newId(),
      orgId: input.orgId,
      issueId: input.issueId,
      authorId,
      body: input.body,
      parentId: input.parentId,
      editedAt: null,
      mentionedUserIds: JSON.stringify(input.mentionedUserIds),
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toComment(row);
}

/** An edit stamps `edited_at`, which the UI shows next to the timestamp. */
export async function updateComment(
  input: UpdateCommentInput,
): Promise<Comment> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(comments)
    .set({ body: input.body, editedAt: stamp, updatedAt: stamp })
    .where(
      and(
        orgPredicate(comments.orgId, input.orgId),
        eq(comments.id, input.commentId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Comment ${input.commentId} not found`);
  return toComment(row);
}

export async function archiveComment(
  orgId: OrgId,
  commentId: CommentId,
): Promise<Comment> {
  const row = getDb()
    .update(comments)
    .set(archivePatch())
    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))
    .returning()
    .get();

  if (!row) throw new Error(`Comment ${commentId} not found`);
  return toComment(row);
}
/**
 * The fan-out hub: one domain event becomes in-app rows, an email draft and/or a digest entry, filtered by each recipient's preferences.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, isEnabled, subscribe
 */
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import { toIsoTimestamp } from "@/types/common";
import { notificationResource, requireFound } from "./_support";
import type {
  ListNotificationsInput,
  MarkNotificationReadInput,
  UpdateNotificationPreferenceInput,
} from "@/schemas/notification";
import type { OrgId, Page, UserId } from "@/types/common";
import type { FlagContext } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type {
  Notification,
  NotificationChannel,
  NotificationKind,
  NotificationPreference,
} from "@/types/notification";

export type NotificationPayload = {
  title: string;
  body: string;
  href: string;
  actorId: UserId | null;
};

/** Channels used when a recipient has never touched their preferences. */
const DEFAULT_CHANNELS: readonly NotificationChannel[] = ["in_app", "email"];

/**
 * Writes one notification row per recipient, each with the channel set that
 * recipient's preferences allow. A recipient who has muted every channel is
 * skipped entirely rather than given a row nobody will ever see.
 */
export async function notify(
  orgId: OrgId,
  kind: NotificationKind,
  recipients: readonly UserId[],
  payload: NotificationPayload,
): Promise<readonly Notification[]> {
  if (recipients.length === 0) return [];

  const org = await orgRepo.findOrgById(orgId);
  const flags: FlagContext = {
    orgId,
    userId: payload.actorId,
    plan: org?.plan ?? "free",
    role: null,
    overrides: org?.settings.enabledFlagOverrides,
  };

  const rows = [];

  for (const recipientId of new Set(recipients)) {
    if (recipientId === payload.actorId) continue;

    const preference = await preferenceRepo.getPreference(
      orgId,
      recipientId,
      kind,
    );
    const channels = resolveChannels(preference, flags);
    if (channels.length === 0) continue;

    rows.push({
      orgId,
      recipientId,
      kind,
      title: payload.title,
      body: payload.body,
      href: payload.href,
      actorId: payload.actorId,
      channels,
    });
  }

  return notificationRepo.insertNotifications(orgId, rows);
}

export async function listNotifications(
  actor: Actor,
  input: ListNotificationsInput,
): Promise<Page<Notification>> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:read",
    notificationResource(input.orgId, input.recipientId),
  );
  return notificationRepo.listNotifications(input);
}

export async function markRead(
  actor: Actor,
  input: MarkNotificationReadInput,
): Promise<Notification> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(input.orgId, actor.userId),
  );
  return notificationRepo.markRead(
    input.orgId,
    input.notificationId,
    toIsoTimestamp(new Date()),
  );
}

export async function markAllRead(
  actor: Actor,
  orgId: OrgId,
): Promise<number> {
  assertOrgScope(actor, orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(orgId, actor.userId),
  );
  return notificationRepo.markAllRead(
    orgId,
    actor.userId,
    toIsoTimestamp(new Date()),
  );
}

export async function updatePreference(
  actor: Actor,
  input: UpdateNotificationPreferenceInput,
): Promise<NotificationPreference> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(input.orgId, input.userId),
  );
  return preferenceRepo.upsertPreference(input);
}

/**
 * Turns a stored preference into the channels one notification will use.
 * `digestOnly` suppresses the immediate email but keeps the in-app row, and
 * the email channel additionally requires the org's `digest_email` plan flag.
 */
export function resolveChannels(
  preference: NotificationPreference | null,
  flags: FlagContext,
): readonly NotificationChannel[] {
  if (preference === null) return DEFAULT_CHANNELS;

  const channels: NotificationChannel[] = [];
  if (preference.inApp) channels.push("in_app");

  const emailAllowed =
    preference.email &&
    (!preference.digestOnly || isEnabled("digest_email", flags));

  if (emailAllowed) channels.push("email");
  return channels;
}

/**
 * The bus wiring. Attached at module load rather than from `event-registry`
 * because the fan-out has no other public entry point — importing this module
 * is what makes an org start receiving notifications.
 */
let registered = false;

function registerFanOut(): void {
  if (registered) return;
  registered = true;

  subscribe("issue.assigned", async (payload) => {
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
    });
  });

  subscribe("issue.overdue", async (payload) => {
    if (payload.assigneeId === null) return;
    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
      title: "An issue is overdue",
      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
      href: `/issues/${payload.issueId}`,
      actorId: null,
    });
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    const watchers = issue
      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
      : [];

    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${payload.issueId}`,
          href: `/issues/${payload.issueId}`,
          actorId: payload.actorId,
        },
      );
    }
  });

  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    await notify(payload.orgId, "member_joined", [org.ownerId], {
      title: "A new member joined",
      body: `${payload.userId} joined as ${payload.role}`,
      href: "/settings/members",
      actorId: payload.userId,
    });
  });
}

registerFanOut();
import type {
  CommentId,
  IssueId,
  SoftDeletable,
  TenantScoped,
  Timestamps,
  UserId,
} from "./common";
import type { User } from "./member";

export interface Comment extends Timestamps, TenantScoped, SoftDeletable {
  readonly id: CommentId;
  readonly issueId: IssueId;
  readonly authorId: UserId;
  readonly body: string;
  readonly parentId: CommentId | null;
  readonly editedAt: string | null;
  readonly mentionedUserIds: readonly UserId[];
}

export interface CommentWithAuthor extends Comment {
  readonly author: User;
}

/** A top-level comment plus its replies, as rendered by `CommentThread`. */
export interface CommentThreadNode {
  readonly comment: CommentWithAuthor;
  readonly replies: readonly CommentWithAuthor[];
}

export interface CommentDraft {
  readonly issueId: IssueId;
  readonly body: string;
  readonly parentId: CommentId | null;
}
import { index, sqliteTable, text } from "drizzle-orm/sqlite-core";
import {
  idColumn,
  softDeleteColumns,
  tenantColumns,
  timestampColumns,
} from "./_shared";

export const comments = sqliteTable(
  "comments",
  {
    id: idColumn(),
    ...tenantColumns,
    issueId: text("issue_id").notNull(),
    authorId: text("author_id").notNull(),
    body: text("body").notNull(),
    parentId: text("parent_id"),
    editedAt: text("edited_at"),
    /** JSON array of user ids, kept denormalised for the mention fan-out. */
    mentionedUserIds: text("mentioned_user_ids").notNull().default("[]"),
    ...timestampColumns,
    ...softDeleteColumns,
  },
  (table) => [
    index("comments_org_issue_idx").on(table.orgId, table.issueId),
    index("comments_org_archived_idx").on(table.orgId, table.archivedAt),
  ],
);

export type CommentRow = typeof comments.$inferSelect;
export type NewCommentRow = typeof comments.$inferInsert;

# Project instructions

This is a TypeScript / Next.js application. Answer questions about it and make
changes to it using the tools available to you in this working directory.

## Answer format contract (mandatory)

Your final message MUST follow the contract for the task type you were given.
The task prompt states its type. If it does not, infer it from the wording.

### `locate`, `reference`, `impact` tasks

