/** Token-bucket refill and exhaustion. */
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { getPlanLimits } from "@/config/plan-limits";
import {
  RATE_LIMIT_BUCKETS,
  consumeRateLimit,
  getBucketConfig,
  resetRateLimits,
  setOrgPlan,
} from "@/lib/rate-limit";
import { ORG_A, ORG_B } from "../helpers/factories";

beforeEach(() => {
  resetRateLimits();
  vi.useFakeTimers();
  vi.setSystemTime(new Date("2026-03-15T12:00:00.000Z"));
});

afterEach(() => {
  vi.useRealTimers();
});

describe("lib/rate-limit", () => {
  it("returns the declared config for a known bucket", () => {
    expect(getBucketConfig("member:invite")).toEqual(
      RATE_LIMIT_BUCKETS["member:invite"],
    );
  });

  it("falls back to a default config for an unknown bucket", () => {
    const config = getBucketConfig("something:new");
    expect(config.capacity).toBeGreaterThan(0);
    expect(config.refillPerMinute).toBeGreaterThan(0);
  });

  it("allows a first request and reports the remaining tokens", async () => {
    const verdict = await consumeRateLimit(ORG_A, "member:invite");
    expect(verdict.allowed).toBe(true);
    expect(verdict.remaining).toBe(19);
  });

  it("exhausts the bucket and then refuses", async () => {
    const capacity = getBucketConfig("auth:password-reset").capacity;
    for (let i = 0; i < capacity; i += 1) {
      expect((await consumeRateLimit(ORG_A, "auth:password-reset")).allowed).toBe(true);
    }

    const denied = await consumeRateLimit(ORG_A, "auth:password-reset");
    expect(denied.allowed).toBe(false);
    expect(denied.remaining).toBe(0);
  });

  it("refills over time at the declared rate", async () => {
    const { capacity, refillPerMinute } = getBucketConfig("auth:password-reset");
    for (let i = 0; i < capacity; i += 1) {
      await consumeRateLimit(ORG_A, "auth:password-reset");
    }
    expect((await consumeRateLimit(ORG_A, "auth:password-reset")).allowed).toBe(false);

    vi.advanceTimersByTime(2 * 60_000);
    const after = await consumeRateLimit(ORG_A, "auth:password-reset");
    expect(after.allowed).toBe(true);
    expect(after.remaining).toBe(2 * refillPerMinute - 1);
  });

  it("never refills past capacity", async () => {
    await consumeRateLimit(ORG_A, "member:invite");
    vi.advanceTimersByTime(24 * 60 * 60_000);

    const verdict = await consumeRateLimit(ORG_A, "member:invite");
    expect(verdict.remaining).toBe(getBucketConfig("member:invite").capacity - 1);
  });

  it("charges the supplied cost", async () => {
    const verdict = await consumeRateLimit(ORG_A, "member:invite", 5);
    expect(verdict.allowed).toBe(true);
    expect(verdict.remaining).toBe(15);
  });

  it("refuses a cost larger than the bucket without spending tokens", async () => {
    const denied = await consumeRateLimit(ORG_A, "auth:password-reset", 999);
    expect(denied.allowed).toBe(false);
    expect(denied.remaining).toBe(getBucketConfig("auth:password-reset").capacity);
  });

  it("keeps buckets separate per org and per key", async () => {
    const capacity = getBucketConfig("auth:password-reset").capacity;
    for (let i = 0; i < capacity; i += 1) {
      await consumeRateLimit(ORG_A, "auth:password-reset");
    }

    expect((await consumeRateLimit(ORG_A, "auth:password-reset")).allowed).toBe(false);
    expect((await consumeRateLimit(ORG_B, "auth:password-reset")).allowed).toBe(true);
    expect((await consumeRateLimit(ORG_A, "member:invite")).allowed).toBe(true);
  });

  it("scales capacity with the org's plan quota rather than hard-coding it", async () => {
    setOrgPlan(ORG_B, "growth");
    const growth = await consumeRateLimit(ORG_B, "member:invite");
    const free = await consumeRateLimit(ORG_A, "member:invite");

    expect(getPlanLimits("growth").apiRequestsPerHour).toBeGreaterThan(
      getPlanLimits("free").apiRequestsPerHour,
    );
    expect(growth.remaining).toBeGreaterThan(free.remaining);
  });

  it("reports a resetAt in the future when the bucket is empty", async () => {
    const capacity = getBucketConfig("auth:password-reset").capacity;
    for (let i = 0; i < capacity; i += 1) {
      await consumeRateLimit(ORG_A, "auth:password-reset");
    }

    const denied = await consumeRateLimit(ORG_A, "auth:password-reset");
    expect(new Date(denied.resetAt).getTime()).toBeGreaterThan(Date.now());
  });
});
"use client";

/**
 * Textarea with an @-mention autocomplete that reports mentioned ids.
 */
import { useRef, useState } from "react";
import { cn } from "@/lib/cn";
import { resolveMentions } from "@/lib/mentions";
import type { UserId } from "@/types/common";
import type { MemberWithUser } from "@/types/member";
import type { ReactElement } from "react";
import {
  applyMention,
  findMentionQuery,
  matchMembers,
  mentionHandle,
  type MentionQuery,
} from "./mention-query";

export type MentionTextareaProps = {
  value: string;
  members: readonly MemberWithUser[];
  onChange: (value: string, mentioned: readonly UserId[]) => void;
};

export function MentionTextarea(
  props: MentionTextareaProps,
): ReactElement | null {
  const { value, members, onChange } = props;
  const ref = useRef<HTMLTextAreaElement | null>(null);
  const [mention, setMention] = useState<MentionQuery | null>(null);

  // `resolveMentions` is the same function the comment service runs on the
  // stored body, so what the composer reports and what the server records
  // cannot drift apart.
  function emit(body: string): void {
    onChange(body, resolveMentions(body, members));
  }

  function handleInput(body: string, caret: number): void {
    setMention(findMentionQuery(body, caret));
    emit(body);
  }

  function choose(member: MemberWithUser): void {
    if (mention === null) return;
    const next = applyMention(value, mention, member);
    setMention(null);
    emit(next.body);
    const element = ref.current;
    if (element !== null) {
      element.focus();
      element.setSelectionRange(next.caret, next.caret);
    }
  }

  const suggestions =
    mention === null ? [] : matchMembers(members, mention.query);

  return (
    <div className="relative">
      <textarea
        ref={ref}
        name="body"
        rows={4}
        value={value}
        className={cn("w-full rounded border p-2 text-sm")}
        placeholder="Leave a comment. Use @ to mention a teammate."
        onChange={(event) =>
          handleInput(event.target.value, event.target.selectionStart)
        }
        onKeyDown={(event) => {
          if (event.key === "Escape" && mention !== null) {
            event.preventDefault();
            setMention(null);
          }
        }}
      />

      {suggestions.length > 0 ? (
        <ul className="absolute z-10 mt-1 w-64 rounded border bg-white shadow">
          {suggestions.map((member) => (
            <li key={member.id}>
              <button
                type="button"
                className="flex w-full justify-between px-2 py-1 text-left text-sm hover:bg-neutral-100"
                onClick={() => choose(member)}
              >
                <span>{member.user.name}</span>
                <span className="text-neutral-500">
                  @{mentionHandle(member)}
                </span>
              </button>
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  );
}
/**
 * The typing-side half of @-mentions.
 *
 * `@/lib/mentions` owns what a finished comment body *means* (which users it
 * mentions); this module owns what the caret is currently doing — where the
 * active `@token` starts, what it filters to, and what the body looks like
 * once a suggestion is accepted. Splitting it that way keeps the textarea from
 * re-deriving the parsing rules the server also applies.
 */
import type { MemberWithUser } from "@/types/member";

/** An in-progress mention: `@` plus the characters typed after it. */
export interface MentionQuery {
  /** Index of the `@` in the body. */
  readonly start: number;
  /** Index just past the last typed character. */
  readonly end: number;
  /** The text after `@`, lowercased for matching. */
  readonly query: string;
}

const MENTION_CHARS = /^[a-zA-Z0-9._-]*$/;

/**
 * Finds the mention the caret sits inside, or `null` when the caret is not in
 * one. A mention only starts at the beginning of the body or after
 * whitespace, so an email address never opens the autocomplete.
 */
export function findMentionQuery(
  body: string,
  caret: number,
): MentionQuery | null {
  const upTo = body.slice(0, Math.max(0, Math.min(caret, body.length)));
  const at = upTo.lastIndexOf("@");
  if (at === -1) return null;

  const before = at === 0 ? "" : upTo[at - 1] ?? "";
  if (before.length > 0 && !/\s/.test(before)) return null;

  const typed = upTo.slice(at + 1);
  if (!MENTION_CHARS.test(typed)) return null;

  return { start: at, end: upTo.length, query: typed.toLowerCase() };
}

/** The handle Taskflow mentions people by: the local part of their email. */
export function mentionHandle(member: MemberWithUser): string {
  const [local = member.user.name] = member.user.email.split("@");
  return local.toLowerCase();
}

/** Members whose handle or display name matches the in-progress query. */
export function matchMembers(
  members: readonly MemberWithUser[],
  query: string,
  limit = 5,
): readonly MemberWithUser[] {
  const needle = query.toLowerCase();
  const matches =
    needle.length === 0
      ? members
      : members.filter(
          (member) =>
            mentionHandle(member).includes(needle) ||
            member.user.name.toLowerCase().includes(needle),
        );
  return matches.slice(0, limit);
}

/** Replaces the in-progress mention with the chosen member's handle. */
export function applyMention(
  body: string,
  mention: MentionQuery,
  member: MemberWithUser,
): { body: string; caret: number } {
  const inserted = `@${mentionHandle(member)} `;
  const next = body.slice(0, mention.start) + inserted + body.slice(mention.end);
  return { body: next, caret: mention.start + inserted.length };
}
/**
 * Private paging helpers shared by the repositories in this directory.
 *
 * Not part of the public data-access surface — repositories re-export nothing
 * from here. Keyset (cursor) pagination is expressed as a row-value comparison
 * so a page boundary is stable even when two rows share a `created_at`.
 */
import { sql } from "drizzle-orm";
import { decodeCursor, encodeCursor } from "./base-repository";
import { makePage } from "@/types/common";
import type { Page } from "@/types/common";
import type { SQL } from "drizzle-orm";
import type { SQLiteColumn } from "drizzle-orm/sqlite-core";

export interface KeysetSort {
  readonly sortColumn: SQLiteColumn;
  readonly idColumn: SQLiteColumn;
}

/**
 * Predicate that resumes a descending listing after `cursor`. Returns
 * `undefined` for a first page or an unparseable cursor — a bad cursor
 * degrades to "start from the top", never to an error page.
 */
export function keysetPredicate(
  sort: KeysetSort,
  cursor: string | null | undefined,
): SQL | undefined {
  if (!cursor) return undefined;
  const decoded = decodeCursor(cursor);
  if (!decoded) return undefined;

  return sql`(${sort.sortColumn}, ${sort.idColumn}) < (${decoded.sortValue}, ${decoded.id})`;
}

/** SQLite tolerates a `LIMIT` of `n + 1`; that extra row is the has-more probe. */
export function probeLimit(limit: number): number {
  return Math.max(1, Math.min(limit, 100)) + 1;
}

/**
 * Turns an over-fetched row array into a `Page`, dropping the probe row and
 * deriving the next cursor from the last row that survived.
 */
export function toPage<TRow, TOut>(
  rows: readonly TRow[],
  limit: number,
  total: number,
  map: (row: TRow) => TOut,
  cursorOf: (row: TRow) => { id: string; sortValue: string },
): Page<TOut> {
  const capped = Math.max(1, Math.min(limit, 100));
  const hasMore = rows.length > capped;
  const visible = hasMore ? rows.slice(0, capped) : rows;
  const last = visible.at(-1);

  const nextCursor =
    hasMore && last
      ? encodeCursor(cursorOf(last).id, cursorOf(last).sortValue)
      : null;

  return makePage(visible.map(map), nextCursor, total);
}

/** Drops the `undefined` slots so `and(...)` never sees a hole. */
export function compact(
  ...predicates: readonly (SQL | undefined)[]
): readonly SQL[] {
  return predicates.filter((value): value is SQL => value !== undefined);
}
/**
 * Primitive identifier and envelope types shared by every Taskflow domain type.
 *
 * Every entity in Taskflow uses opaque branded string ids so that an `IssueId`
 * can never be silently passed where a `ProjectId` is expected. Ids are ULID
 * strings at runtime; the brand exists only at the type level.
 */

declare const brand: unique symbol;

/** Attaches a compile-time-only tag to a primitive type. */
export type Branded<T, B extends string> = T & { readonly [brand]: B };

export type UserId = Branded<string, "UserId">;
export type OrgId = Branded<string, "OrgId">;
export type ProjectId = Branded<string, "ProjectId">;
export type IssueId = Branded<string, "IssueId">;
export type CommentId = Branded<string, "CommentId">;
export type MemberId = Branded<string, "MemberId">;
export type NotificationId = Branded<string, "NotificationId">;
export type ActivityId = Branded<string, "ActivityId">;
export type InvitationId = Branded<string, "InvitationId">;
export type LabelId = Branded<string, "LabelId">;
export type AttachmentId = Branded<string, "AttachmentId">;
export type SubscriptionId = Branded<string, "SubscriptionId">;
export type SessionId = Branded<string, "SessionId">;
export type WebhookId = Branded<string, "WebhookId">;

/** Union of every branded id used in the app, for generic id helpers. */
export type AnyId =
  | UserId
  | OrgId
  | ProjectId
  | IssueId
  | CommentId
  | MemberId
  | NotificationId
  | ActivityId
  | InvitationId
  | LabelId
  | AttachmentId
  | SubscriptionId
  | SessionId
  | WebhookId;

/** ISO-8601 timestamp string as stored in SQLite text columns. */
export type IsoTimestamp = Branded<string, "IsoTimestamp">;

/** Rows carrying the standard created/updated bookkeeping columns. */
export interface Timestamps {
  readonly createdAt: IsoTimestamp;
  readonly updatedAt: IsoTimestamp;
}

/**
 * Soft-delete marker. `archivedAt === null` means the row is live. Repositories
 * must filter on this via the helpers in `src/lib/soft-delete.ts` rather than
 * writing the predicate by hand.
 */
export interface SoftDeletable {
  readonly archivedAt: IsoTimestamp | null;
}

/** Rows that belong to exactly one tenant. Enforced by `src/lib/tenant.ts`. */
export interface TenantScoped {
  readonly orgId: OrgId;
}

export type SortDirection = "asc" | "desc";

export interface SortSpec<TField extends string = string> {
  readonly field: TField;
  readonly direction: SortDirection;
}

/** Cursor pagination request shared by every repository `list*` method. */
export interface PageRequest {
  readonly limit: number;
  readonly cursor?: string | null;
}

/** Cursor pagination response shared by every repository `list*` method. */
export interface Page<T> {
  readonly items: readonly T[];
  readonly nextCursor: string | null;
  readonly total: number;
}

/** Options accepted by every soft-delete-aware repository read. */
export interface ArchiveScope {
  readonly includeArchived?: boolean;
}

export function makePage<T>(
  items: readonly T[],
  nextCursor: string | null,
  total: number,
): Page<T> {
  return { items, nextCursor, total };
}

export function toIsoTimestamp(value: Date | string): IsoTimestamp {
  const date = typeof value === "string" ? new Date(value) : value;
  return date.toISOString() as IsoTimestamp;
}

